# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA İBADETLERİN KABUL VE GEÇERLİLİK ŞARTLARI</text>\n  <rect x="20" y="48" width="210" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. İMAN VE NİYET</text>\n  <text x="35" y="98" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">İman:</tspan> İbadetlerin Allah katında</text>\n  <text x="42" y="114" font-size="11" fill="#1e3a8a">değer kazanmasının ilk temelidir.</text>\n  <text x="35" y="138" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Niyet:</tspan> İbadeti alışkanlıktan</text>\n  <text x="42" y="154" font-size="11" fill="#1e3a8a">ayırıp bilinçli kulluğa dönüştürür.</text>\n  <rect x="35" y="172" width="180" height="54" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">"Ameller niyetlere göredir."</text>\n  <text x="125" y="210" text-anchor="middle" font-size="10" fill="#1e3a8a">(Hadis-i Şerif)</text>\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. İHLAS (SAMİMİYET)</text>\n  <text x="260" y="98" font-size="11" fill="#14532d">• İbadeti dünyevi çıkar, övgü</text>\n  <text x="267" y="114" font-size="11" fill="#14532d">veya gösteriş (riya) karıştırmadan</text>\n  <text x="267" y="130" font-size="11" font-weight="bold" fill="#166534">Allah rızası için yapmaktır.</text>\n  <text x="260" y="154" font-size="11" fill="#14532d">• İbadetin ruhu ve özüdür.</text>\n  <rect x="260" y="172" width="180" height="54" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="350" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">"Dini Allah\'a halis kılarak</text>\n  <text x="350" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">O\'na kulluk edin." (Zümer, 2)</text>\n  <rect x="470" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">3. SÜNNETE UYGUNLUK</text>\n  <text x="485" y="98" font-size="11" fill="#78350f">• <tspan font-weight="bold">İttiba:</tspan> İbadetleri Kur\'an\'ın</text>\n  <text x="492" y="114" font-size="11" fill="#78350f">emrettiği ve Hz. Peygamber\'in</text>\n  <text x="492" y="130" font-size="11" fill="#78350f">uyguladığı şekilde yerine getirmek.</text>\n  <text x="485" y="154" font-size="11" fill="#78350f">• Bid\'at ve aşırılıktan uzak durmak.</text>\n  <rect x="485" y="172" width="180" height="54" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="575" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">"Beni nasıl namaz kılarken</text>\n  <text x="575" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">gördüyseniz öyle kılın."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İHLAS — RİYA KARŞITLIĞI VE MAUN SURESİNİN UYARISI</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İhlaslı (Samimi) İbadet</text>\n  <text x="42" y="98" font-size="11.5" fill="#14532d">• Hedef: <tspan font-weight="bold">Rıza-i İlahi</tspan> (Allah\'ın hoşnutluğu)</text>\n  <text x="42" y="122" font-size="11.5" fill="#14532d">• Gizli ve açık her ortamda aynı bilinç ve</text>\n  <text x="50" y="138" font-size="11.5" fill="#14532d">huşu (saygı ve tevazu) ile eda edilir.</text>\n  <text x="42" y="162" font-size="11.5" fill="#14532d">• İnsanı ahlaki olgunluğa (ihsan bilincine)</text>\n  <text x="50" y="178" font-size="11.5" fill="#14532d">ve toplumsal yardımlaşmaya yöneltir.</text>\n  <rect x="42" y="194" width="280" height="34" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="182" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Sonuç: Sevap, manevi huzur ve kabul (makbul amel)</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Riyakâr (Gösterişçi) Davranış</text>\n  <text x="378" y="98" font-size="11.5" fill="#7f1d1d">• Hedef: İnsanların övgüsü, şöhret (süm\'a) ve çıkar</text>\n  <text x="378" y="122" font-size="11.5" fill="#7f1d1d">• Hz. Peygamber tarafından <tspan font-weight="bold">"küçük şirk"</tspan> (gizli şirk)</text>\n  <text x="386" y="138" font-size="11.5" fill="#7f1d1d">olarak nitelendirilmiştir.</text>\n  <text x="378" y="162" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Maun Suresi (4-7):</tspan> Namazından gafil olup</text>\n  <text x="386" y="178" font-size="11.5" fill="#7f1d1d">gösteriş yapanlar ve yardımı engelleyenler kınanır.</text>\n  <rect x="378" y="194" width="280" height="34" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="517" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Sonuç: Amelin sevabını ve manevi değerini boşa çıkarır</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FIKHİ GEÇERLİLİK (SIHHAT) VE MANEVİ KABUL KAVRAMLARI</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Biçimsel Doğruluk: Sıhhat ve Eda</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Sahih İbadet:</tspan> Farz, vacip ve sünnetlerine,</text>\n  <text x="50" y="112" font-size="11.5" fill="#1e3a8a">rükün ve şartlarına uygun yapılan ibadettir.</text>\n  <text x="42" y="136" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Batıl / Fâsit:</tspan> Kurucu unsuru (rüknü) veya</text>\n  <text x="50" y="152" font-size="11.5" fill="#1e3a8a">şartı eksik olduğu için geçersiz olan ibadettir.</text>\n  <text x="42" y="176" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Bid\'at:</tspan> Dinde aslı olmayan sonradan</text>\n  <text x="50" y="192" font-size="11.5" fill="#1e3a8a">uydurulmuş uygulamalar (reddedilmiştir).</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Manevi Boyut: Huşu, İhsan ve Takva</text>\n  <text x="378" y="96" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Huşu:</tspan> Kalbin Allah\'a saygı, sevgi ve</text>\n  <text x="386" y="112" font-size="11.5" fill="#581c87">derin bir odaklanmayla yönelmesidir.</text>\n  <text x="378" y="136" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">İhsan:</tspan> Allah\'ı görüyormuşçasına</text>\n  <text x="386" y="152" font-size="11.5" fill="#581c87">bilinçli ve özenli kulluk etmektir.</text>\n  <text x="378" y="176" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Takva:</tspan> İbadetlerin nihai gayesi olan</text>\n  <text x="386" y="192" font-size="11.5" fill="#581c87">günahlardan korunma ve sorumluluk bilincidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
